#!/bin/bash

mkdir -p stitch_resources

download_screen() {
    local id=$1
    local screenshot_url=$2
    local html_url=$3
    
    echo "Downloading screen: $id"
    mkdir -p "stitch_resources/$id"
    
    if [ -n "$screenshot_url" ]; then
        curl -L "$screenshot_url" -o "stitch_resources/$id/screenshot.png"
    fi
    
    if [ -n "$html_url" ]; then
        curl -L "$html_url" -o "stitch_resources/$id/index.html"
    fi
}

